-- ----------------------------
-- Table structure for ad_profile
-- ----------------------------
DROP TABLE IF EXISTS `ad_profile`;
CREATE TABLE `ad_profile`  (
  `ap_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '資料主鍵',
  `ap_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '資料編號',
  `ap_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '資料標題',
