-- ----------------------------
-- Table structure for order_sheet
-- ----------------------------
DROP TABLE IF EXISTS `order_sheet`;
CREATE TABLE `order_sheet`  (
  `os_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '資料代號',
  `os_no` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '訂單編號',
  `os_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'Y' COMMENT '訂單狀態 (Y/正常 , N/作癈)',
  `os_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '詢貨人姓名',
  `os_sex` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'M' COMMENT '性別',
  `os_company` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '詢貨公司',
  `os_dep` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '部門',
  `os_post` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '職務',
  `os_fax` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '詢貨人傳真',
  `os_phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '詢貨人電話',
  `os_cellphone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '詢貨人行動電話',
  `os_email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '電子信箱',
  `os_county` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '詢貨人居住城市',
  `os_city` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '詢貨人居住鄉鎮',
  `os_zipcode` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '詢貨人郵遞區號',
  `os_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '詢貨人地址',
  `os_contact` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '連絡方式',
  `os_info` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '取得資訊方式',
  `os_shop_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '預計採購時間',
  `os_budget` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '是否編入預算',
  `os_memo` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL COMMENT '使用者訂購備註',
  `os_paymethod` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '付款方式\r(ezship_cvs_pick/超商取貨 ,(ezship_cvs_cod/超商取貨付款 ,\r\n(ezship_cod/貨到付款)',
  `os_logistics` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '物流方式',
  `os_freight` int NOT NULL DEFAULT 0 COMMENT '訂單運費',
  `os_getbonus` int NOT NULL DEFAULT 0 COMMENT '贈送紅利點數',
  `os_use_maxbonus` int NOT NULL DEFAULT 0 COMMENT '本次訂單最多能使用的紅利點數',
  `os_usebonus` int NOT NULL DEFAULT 0 COMMENT '使用紅利點數',
  `os_bonus_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'N' COMMENT '饋贈紅利審核發放狀態 (Y/N)',
  `os_discount` int NOT NULL DEFAULT 0 COMMENT '紅利換算折讓金額',
  `os_total` int NOT NULL DEFAULT 0 COMMENT '訂單總金額',
  `mp_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '會員代碼',
  `os_logistics_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '到貨時間',
  `os_ship` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'N' COMMENT '出貨與否 (Y/N) / 是否回覆詢價單',
  `os_collect` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'N' COMMENT '收款與否 (Y/N)',
  `os_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '類別識別碼',
  `os_lang` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '語系',
  `os_createdate` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '資料建立日期時間',
  `os_createuser` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '資料建立者帳號',
  `os_modifydate` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '資料最後修改日期時間',
  `os_modifyuser` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '資料最後修改者帳號',
  PRIMARY KEY (`os_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_520_ci ROW_FORMAT = DYNAMIC;

