  `pd_revisit_after` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '7' COMMENT '瀏覽器重訪時間間隔',
  `pd_keywords` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL COMMENT '頁面關鍵字',
