-- ----------------------------
-- Table structure for smtp_times
-- ----------------------------
DROP TABLE IF EXISTS `smtp_times`;
CREATE TABLE `smtp_times`  (
  `st_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '資料主鍵',
  `st_hostname` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '外送郵件伺服器名稱(SMTP)',
  `st_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '使用狀態(Y/N)',
  `st_times` int NOT NULL DEFAULT 0 COMMENT '可寄次數',
  `st_send_times` int NOT NULL DEFAULT 0 COMMENT '已寄次數',
  `st_authport` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '埠號(Port)',
  `st_authstatus` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '認證狀態(Y是/N否/O使用 Office SMTP Server (587 Port))',
  `st_ssluse` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '是否使用ssl驗證',
  `st_authaccount` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '認證帳號',
  `st_authpassword` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '認證密碼',
  `st_serviceemailname` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL COMMENT '寄件者名稱',
  `st_serviceemail` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL COMMENT '寄件者信箱',
  `st_showseq` int NOT NULL DEFAULT 0 COMMENT '資料排序',
  `st_code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '類別識別碼',
  `st_lang` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '語系',
  `st_createdate` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '建檔日期',
  `st_createuser` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '建檔人員',
  `st_modifydate` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '最後修改日期',
  `st_modifyuser` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '' COMMENT '最後修改人員',
  PRIMARY KEY (`st_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_520_ci ROW_FORMAT = DYNAMIC;

